begin;select plan(28);
select has_table('public','manual_service_connections','manual services exist');select has_table('public','manual_service_challenges','manual challenges exist');
select ok((select relforcerowsecurity from pg_class where oid='public.manual_service_connections'::regclass),'manual service FORCE RLS');select ok((select relforcerowsecurity from pg_class where oid='public.manual_service_challenges'::regclass),'manual challenge FORCE RLS');
select table_privs_are('public','manual_service_connections','anon',array[]::text[],'anonymous has no access');select table_privs_are('public','manual_service_connections','authenticated',array['SELECT'],'browser cannot self verify');select table_privs_are('public','manual_service_challenges','authenticated',array['SELECT'],'browser cannot complete challenges');
select function_privs_are('public','verify_manual_service',array['uuid','uuid','text','text'],'authenticated',array[]::text[],'verification is service only');select function_privs_are('public','claim_expansion_four_connections',array['integer','uuid'],'authenticated',array[]::text[],'claims are service only');
select col_has_check('public','manual_service_connections','verification_status','verification state constrained');select col_has_check('public','manual_service_connections','service_category','categories constrained');select col_has_check('public','provider_asset_bindings','asset_type','expanded asset types constrained');
select is(public.trust_provider_family('spotify'),'spotify','Spotify family');select is(public.trust_provider_family('snapchat'),'snap','Snap family');select is(public.trust_provider_family('pinterest'),'pinterest','Pinterest family');select is(public.trust_provider_family('manual_service'),'manual','manual family');
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,confirmation_token,recovery_token,email_change_token_new,email_change)values('00000000-0000-0000-0000-000000000000','85000000-0000-4000-8000-000000000001','authenticated','authenticated','stage85@example.com',crypt('pw',gen_salt('bf')),now(),'{}','{}',now(),now(),'','','','');
update public.creators set display_name='Stage 8.5',public_slug='stage-85'where owner_user_id='85000000-0000-4000-8000-000000000001';
insert into public.creator_identity_profiles(creator_id,public_display_name)select id,'Stage 8.5'from public.creators where public_slug='stage-85'on conflict(creator_id)do nothing;
insert into public.connected_accounts(id,creator_id,platform,account_type,label,url,is_public,external_account_id,external_account_name,external_account_url,provider_status,connection_health,watch_enabled,auto_create_drafts,auto_send)select'85000000-0000-4000-8000-000000000010',id,'pinterest','official','Pinterest','https://www.pinterest.com/creator/',true,'pin-user','Creator','https://www.pinterest.com/creator/','ready','healthy',true,true,false from public.creators where public_slug='stage-85';
insert into public.manual_service_connections(id,creator_id,identity_profile_id,service_name,service_category,canonical_url,normalized_hostname,display_name)select'85000000-0000-4000-8000-000000000020',c.id,p.id,'Example','other','https://example.com/profile','example.com','Example'from public.creators c join public.creator_identity_profiles p on p.creator_id=c.id where c.public_slug='stage-85';
set local role service_role;select set_config('request.jwt.claim.role','service_role',true);
select lives_ok($$select public.select_provider_asset('85000000-0000-4000-8000-000000000010','pinterest','pinterest_board','pin-user','','Creator','creator','https://www.pinterest.com/creator/','{"privacy":"PUBLIC"}')$$,'select public board');
select is((select count(*)::integer from public.provider_asset_bindings where provider='pinterest'),1,'one board binding');select is((select approval_required from public.provider_asset_bindings where provider='pinterest'),true,'approval required');select is((select auto_send from public.connected_accounts where id='85000000-0000-4000-8000-000000000010'),false,'no provider publishing');
select is((select verification_status from public.manual_service_connections where id='85000000-0000-4000-8000-000000000020'),'unverified','manual service starts unverified');select is((select official from public.manual_service_connections where id='85000000-0000-4000-8000-000000000020'),false,'manual service starts unofficial');
select throws_ok($$update public.manual_service_connections set official=true where id='85000000-0000-4000-8000-000000000020'$$,'23514',null,'unverified service cannot be official');
select lives_ok($$select count(*) from public.claim_expansion_four_connections(20,'85000000-0000-4000-8000-000000000099')$$,'worker claims due source');select is((select lease_owner from public.connected_accounts where id='85000000-0000-4000-8000-000000000010'),'85000000-0000-4000-8000-000000000099'::uuid,'lease owner recorded');
reset role;select is((select count(*)::integer from public.creator_emergencies),0,'no emergency activation');select is((select count(*)::integer from public.update_deliveries),0,'no delivery queue');select is((select count(*)::integer from public.provider_product_entitlements where provider in('spotify','snapchat','pinterest')and status='approved'),0,'gated access never defaults approved');
select*from finish();rollback;
